'use strict';
(()=>{const $=s=>document.querySelector(s),G=GeoEngine,W=SpatiaWorkspace,C=SpatiaGIS;proj4.defs('EPSG:5186','+proj=tmerc +lat_0=38 +lon_0=127 +k=1 +x_0=200000 +y_0=600000 +ellps=GRS80 +units=m +no_defs');let model;try{model=G.validate(JSON.parse(localStorage.getItem(W.MODEL_KEY)))}catch{model=G.seed()}let ref=model.georeference,footprint=null,outline,external=null,layer;const map=L.map('gisMap',{zoomControl:true}).setView([36.2,127.5],6);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19}).addTo(map);$('#modelSummary').textContent=model.name+' · 건물 ID '+W.buildingId(model)+' · '+model.elements.length+'개 구조물';function status(t){$('#gisStatus').textContent=t}function fill(r){for(const k of ['crs','east','north','rotation','scale','height'])$('#'+k).value=r[k];$('#referenceSource').value=r.source}function display(){footprint=C.footprint(model,ref,proj4);if(outline)map.removeLayer(outline);outline=L.geoJSON(footprint,{style:{color:'#176b53',weight:2,fillOpacity:.25}}).addTo(map);outline.bindPopup(()=>{const p=document.createElement('p');p.textContent=model.name+' · '+ref.source;return p});map.fitBounds(outline.getBounds(),{maxZoom:18,padding:[25,25]});$('#exportFootprint').disabled=false;status('좌표 기준 표시 완료 · 사용자 입력 기준 / 측량 정합 미검증');screen()}
function screen(){if(!external||!footprint)return;const matches=C.screen(footprint,external);$('#layerSummary').textContent='출처: '+$('#layerSource').value.trim()+' · '+external.features.length+'개 구역 중 경계상자 중첩 후보 '+matches.length+'개';const host=$('#layerResults');host.replaceChildren();for(const m of matches){const p=document.createElement('p');p.textContent=m.id+' · '+m.name+' — '+m.method;host.append(p)}}
if(ref){fill(ref);try{display()}catch(e){status(e.message)}}else status('아직 지도 기준점이 없습니다. 좌표 기준을 입력하세요.');if(model.siteLocation&&Number.isFinite(model.siteLocation.latitude)&&Number.isFinite(model.siteLocation.longitude)){$('#siteOrigin').hidden=false;$('#siteOrigin').onclick=()=>{$('#lat').value=model.siteLocation.latitude;$('#lon').value=model.siteLocation.longitude;$('#referenceSource').value=model.siteLocation.source+' · IfcSite 위치만 사용 / 원점·회전 미검증';convert()}}function convert(){const lat=+$('#lat').value,lon=+$('#lon').value;if(!$('#lat').value||!$('#lon').value||!Number.isFinite(lat)||Math.abs(lat)>85||!Number.isFinite(lon)||Math.abs(lon)>180)return status('유효한 경위도를 입력하세요.');if($('#crs').value==='EPSG:5186'&&(lon<124||lon>132||lat<32||lat>40))return status('EPSG:5186은 한국 중부 지역에 사용하세요. 이 위치는 EPSG:3857을 선택하세요.');const [east,north]=proj4('EPSG:4326',$('#crs').value,[lon,lat]);$('#east').value=east.toFixed(4);$('#north').value=north.toFixed(4);status('원점 입력란을 변환했습니다. 출처를 입력한 후 저장하세요.')}$('#convertOrigin').onclick=convert;
$('#referenceForm').onsubmit=e=>{e.preventDefault();try{const raw={source:$('#referenceSource').value.trim(),crs:$('#crs').value};for(const k of ['east','north','rotation','scale','height'])raw[k]=+$('#'+k).value;const next=C.reference(raw);const valid=G.validate({...model,georeference:next});localStorage.setItem(W.MODEL_KEY,JSON.stringify(valid));model=valid;ref=next;display()}catch(e){status(e.message)}};
$('#exportFootprint').onclick=()=>{const blob=new Blob([JSON.stringify({type:'FeatureCollection',features:[footprint]},null,2)],{type:'application/geo+json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=W.buildingId(model)+'-footprint.geojson';a.click();URL.revokeObjectURL(url)};
$('#layerFile').onchange=async()=>{try{const f=$('#layerFile').files[0];if(!f)return;if(!$('#layerSource').value.trim())throw Error('자료 출처·기준일을 먼저 입력하세요.');if(f.size>2e6)throw Error('GeoJSON은 2MB 이하로 선택하세요.');const next=C.polygons(JSON.parse(await f.text()));if(layer)map.removeLayer(layer);external=next;layer=L.geoJSON(next,{style:{color:'#b27852',weight:1,fillOpacity:.2}}).addTo(map);if(!footprint)$('#layerSummary').textContent='자료를 읽었습니다. 건물의 좌표 기준을 먼저 저장하세요.';screen()}catch(e){$('#layerSummary').textContent=e.message;$('#layerFile').value=''}};
})();
